<template><ArtifactDetailShell kind="研究" :title="data?.topic||data?.name||'研究详情'" :artifact-ref="refId" :loading="loading" :error="error" :selection="{research_ref:refId}" selection-label="研究" :selection-title="data?.topic||data?.name"><template v-if="data"><p class="intro">这份研究汇总了当前账号授权的数据，用于后续内容策略与选题判断。</p><el-descriptions :column="2" border><el-descriptions-item label="完成情况">{{statusLabel(data.status)}}</el-descriptions-item><el-descriptions-item label="更新时间">{{formatTime(data.updated_at)}}</el-descriptions-item><el-descriptions-item label="研究摘要" :span="2">{{data.summary||'暂无研究摘要'}}</el-descriptions-item></el-descriptions><h2>研究结论</h2><div v-for="(items,key) in data.findings" :key="key" class="block"><strong>{{findingLabel(key)}}</strong><p>{{items.length?items:'暂无结论'}}</p></div><h2>数据来源</h2><div class="source-grid"><span>来源账号：{{count('account_refs')}}</span><span>来源笔记：{{Number(data.source_metadata.note_count||0)}}</span><span>来源评论：{{Number(data.source_metadata.comment_count||0)}}</span><span>证据引用：{{count('note_refs')}}</span></div><h2>内容机会</h2><el-card v-for="item in data.opportunities" :key="item.ref" shadow="never"><strong>{{item.title}}</strong><p>{{item.angle}} · {{item.evidence_summary}}</p></el-card><h2>缺失数据与限制</h2><el-empty v-if="!data.limitations.length&&!data.warnings.length" description="当前没有已知缺失项"/><el-alert v-else :title="[...data.warnings,...data.limitations].join('；')" type="warning" :closable="false"/></template></ArtifactDetailShell></template>
<script setup lang="ts">
import{computed,onBeforeUnmount,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{getResearchDetail}from'@/api/unifiedAgent';import{useAgentChatStore}from'@/stores/agentChat';import{formatTime,statusLabel}from'@/utils/presentation';import type{ResearchDetail}from'@/types/productRead';import ArtifactDetailShell from'@/components/ArtifactDetailShell.vue'
const route=useRoute(),store=useAgentChatStore(),refId=computed(()=>Number(route.params.artifactRef)),loading=ref(true),error=ref(''),data=ref<ResearchDetail|null>(null),controller=new AbortController();const labels:Record<string,string>={persona_patterns:'目标人群特征',content_pillars:'内容支柱',content_insights:'内容洞察',suggestions:'行动建议'};const findingLabel=(key:string)=>labels[key]||'其他结论';const count=(key:string)=>Array.isArray(data.value?.source_metadata[key])?(data.value?.source_metadata[key]as unknown[]).length:0
onMounted(async()=>{if(!store.account_ref){error.value='请先选择账号';loading.value=false;return}try{data.value=await getResearchDetail(refId.value,store.account_ref,controller.signal)}catch(e){if(!controller.signal.aborted)error.value=store.clearRejectedAccount(e)?'账号不可用，请重新选择账号':'研究详情加载失败'}finally{loading.value=false}});onBeforeUnmount(()=>controller.abort())
</script>
<style scoped>.intro{color:#64748b;line-height:1.7}h2{margin-top:28px;font-size:17px}.block,.el-card{margin:10px 0}.block p{color:#657083;white-space:pre-wrap}.source-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.source-grid span{padding:12px;border-radius:8px;background:#f8fafc}</style>
